acceptance_cmd:
set -eu
L=ops/injection_lint.py
test -f "$L" || { echo "FAIL: $L is gone — re-derive this criterion"; exit 1; }
grep -Eq 'strip_comments|re\.sub\(r?"?/\*|//\[\^' "$L" || { echo "FAIL: injection_lint still counts occurrences without stripping comments"; exit 1; }
T=$(ls ops/tests/test_injection_lint.* 2>/dev/null | head -1)
test -n "$T" || { echo "FAIL: no test file for injection_lint — the fix has no negative control"; exit 1; }
grep -Eqi 'comment' "$T" || { echo "FAIL: no test pins that a mention inside a comment does not count"; exit 1; }
grep -Eqi 'nested|enum|typealias' "$T" || { echo "FAIL: no test pins that a nested type may precede the hot-reload property"; exit 1; }
grep -Eqi 'missing|mismatch|fail' "$T" || { echo "FAIL: no test pins that a genuinely missing pairing still fails"; exit 1; }
./ops/injection_lint.py --baseline-check >/dev/null 2>&1 || { echo "FAIL: baseline-check does not pass after the fix"; exit 1; }
echo OK
